const express = require("express");    //Imports the Express library 
const bodyParser  = require("body -parser"); // Imports the body -parser middleware module
const app = express();     // Creates an Express application 
app.use (bodyParser.urlencoded ({ extended: true }));
let feedbacks = [];           // In -memory storage (no DB for simplicity)
app.get ("/", (req, res) => {        // Defines a GET route for the root path /. res.send ("Welcome to Feedback App!"); });
app.post ("/feedback", (req, res) => {         // Defines a POST route at /feedback 
  feedbacks.push ({ name: req.body.name, message: req.body.message  });
  res.send ("Thanks for your feedback!"); });
app.get ("/all -feedback", (req, res) => {
  res.json (feedbacks); });
app.listen (3000, () => console.log("App running on http://localhost:3000 "));
           // Starts the HTTP server and listens for incoming requests on port 3000.Workshop using end to end layering of components and cloud 
