Cloud Native Architecture for Modern Platforms - 21CSE477TWorkshop for moving from monolithic to microservices components
Step 1: Monolithic Application
 A single Express app with Users  and Products  in one codebase. // monolith -app.js
const express = require("express");
const app = express();
app.use (express.json ());
// Users endpoint
app.get ("/users", (req, res) => {
  res.json ([{ id: 1, name: "Justina" }]);
});
// Products endpoint
app.get ("/products", (req, res) => {
  res.json ([{ id: 101, name: "Laptop" }]);
});
app.listen (3000, () => console.log("Monolith running on port 3000"));

