Step 2: Break into Microservices
a) User Service
// user -service.js
const express = require("express");
const app = express();
app.get ("/users", (req, res) => {
  res.json ([{ id: 1, name: "Justina" }, { id: 2, name: "Michael" }]);
});
app.listen (3001, () => console.log("User Service running on port 3001"));

